    public function testApprovedVisualPolicyMetadataDoesNotCertifyUnlicensedArtwork(bool $hardReject):void
    {
        foreach(DigiForge\POD\TransformationEngineContract::ENGINES as $engine){$rubric=DigiForge\POD\TransformationVisualContract::rubric($engine,$engine==='AI_TRANSFORM'?'controlled_painterly_illustration':null);self::assertIsArray($rubric);self::assertNotEmpty($rubric['critical_dimensions']);self::assertSame('1.2',$rubric['visual_policy_version']);self::assertSame(2,$rubric['critical_dimension_minimum']);self::assertSame(2.5,$rubric['applicable_dimension_mean_minimum']);self::assertSame(['positive'=>5,'negative'=>3,'edge'=>2],$rubric['initial_samples_per_mode']);self::assertSame(2,$rubric['required_independent_reviewers']);self::assertTrue($rubric['thresholds_approved']);self::assertFalse($rubric['owner_designated_reviewer_verified']);}
        [$request,$path,$rights]=$this->fixture();$s=new DigiForge\POD\TransformationWorkflow();$key=wp_generate_uuid4();self::assertNotWPError($s->create('personalized_pod',$key,$request,$path,$rights));self::assertNotWPError($s->verifyInput('personalized_pod',$key));self::assertNotWPError($s->importResult('personalized_pod',$key,$path,['evidence_kind'=>'SYNTHETIC_TEST_ONLY','provider'=>'offline_fixture','model'=>'fixture','prompt_version'=>'fixture-1','config_sha256'=>hash('sha256','fixture')]));self::assertNotWPError($s->technicalQa('personalized_pod',$key));self::assertNotWPError($s->requestReview('personalized_pod',$key));
        $mockupPath=tempnam(sys_get_temp_dir(),'df-visual-mockup-');$this->paths[]=$mockupPath;file_put_contents($mockupPath,DigiForge\POD\RasterArtworkCodec::encode(4,4,str_repeat("\x80\x80\x80\xff",16)));$mockup=(new DigiForge\POD\RenderArtifactStore())->retain($mockupPath,(new DigiForge\POD\RenderArtifactVerifier())->readArtifact($mockupPath),'personalized_pod');self::assertNotWPError($mockup);
        $job=$s->read('personalized_pod',$key);$rubric=DigiForge\POD\TransformationVisualContract::rubric('PET_PORTRAIT');$review=['visual_contract_version'=>'1.1','scores'=>array_fill_keys(array_merge($rubric['critical_dimensions'],$rubric['additional_dimensions']),3),'hard_rejects'=>array_fill_keys($rubric['hard_rejects'],false),'source_sha256'=>$job['source']['sha256'],'reference_sha256'=>$rights['result_asset_sha256'],'output_sha256'=>$job['result']['sha256'],'template_sha256'=>$request['template_sha256'],'print_mockup'=>$mockup,'decision'=>'RECORD_REVIEW','reason'=>'Synthetic plumbing, no quality certification'];
        $bad=$review;$bad['thresholds_approved']=true;self::assertWPError($s->recordVisualReview('personalized_pod',$key,$bad));$bad=$review;$bad['scores']['species']=4;self::assertWPError($s->recordVisualReview('personalized_pod',$key,$bad));$bad=$review;$bad['source_sha256']=hash('sha256','wrong');self::assertWPError($s->recordVisualReview('personalized_pod',$key,$bad));self::assertWPError($s->recordVisualReview('digital',$key,$review));
        if($hardReject)$review['hard_rejects']['unauthorized_subject_change']=true;
        $record=$s->recordVisualReview('personalized_pod',$key,$review);self::assertNotWPError($record);self::assertSame($hardReject?'REJECTED':'HUMAN_REVIEW',$record['state']);self::assertSame($hardReject?'REJECTED':'VISUAL_REVIEW_PENDING',$record['visual_review']['visual_acceptance_state']);self::assertSame('1.2',$record['visual_review']['visual_policy_version']);self::assertTrue($record['visual_review']['thresholds_approved']);self::assertFalse($record['visual_review']['owner_designated_reviewer_verified']);self::assertFalse($record['visual_review']['commercial_quality_certified']);self::assertFalse($record['production_ready']);self::assertGreaterThan(0,$record['visual_review']['reviewed_by']);self::assertSame($record['event_sha256'],$s->recordVisualReview('personalized_pod',$key,$review)['event_sha256']);$bad=$review;$bad['scores']['species']=2;self::assertWPError($s->recordVisualReview('personalized_pod',$key,$bad));
        $storedMockup=DigiForge\ProductFactory\AssetStorage::absolutePath($mockup['storage_reference']);$originalMockup=file_get_contents($storedMockup);try{file_put_contents($storedMockup,'changed');self::assertWPError($s->visualCertification('personalized_pod',$key));}finally{file_put_contents($storedMockup,$originalMockup);}
        $status=$s->visualCertification('personalized_pod',$key);self::assertNotWPError($status);self::assertContains('LICENSED_FIXTURES_REQUIRED',$status['blockers']);self::assertContains('OWNER_DESIGNATED_REVIEWERS_AND_TWO_SIGNOFFS_REQUIRED',$status['blockers']);self::assertContains('APPROVED_INITIAL_PER_MODE_FIXTURE_SET_REQUIRED',$status['blockers']);self::assertSame('RELEASE_BLOCKED',$status['release_state']);
    }
    public static function visualReviewCases():array{return [[false],[true]];}
